using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_CorruptionSource", menuName = "Data/Battle/Logics/Enemy Action/Corruption Source Target")]
public class EnemyActionLogic_CorruptionSource : EnemyActionLogic
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		GameObject corruptionSource = currentCorruptedAnimals.GetCorruptionSource();
		if (!(corruptionSource == null))
		{
			if (actionAmount == EffectsValues.NO_VALUE)
			{
				battleAction.CastTarget(corruptionSource, source);
			}
			else
			{
				battleAction.CastTargetAmount(corruptionSource, actionAmount, source);
			}
		}
	}
}
